import json, os, tempfile

PATH = os.path.join('delivery', 'ai_replies.jsonl')

def _load(path):
    rows = []
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line:
                    rows.append(json.loads(line))
    return rows

def _atomic_write(path, rows):
    d = os.path.dirname(path) or '.'
    os.makedirs(d, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix='.tmp_')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            for r in rows:
                f.write(json.dumps(r, ensure_ascii=False) + '\n')
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.remove(tmp)
        raise

def main(arguments):
    rid = arguments['id']
    msg = arguments['message']
    if not isinstance(rid, str) or not rid:
        raise ValueError('id must be non-empty string')
    if not isinstance(msg, str):
        raise ValueError('message must be string')
    rows = _load(PATH)
    for r in rows:
        if r.get('id') == rid:
            if r.get('message') == msg:
                return {'id': rid, 'status': 'delivered_simulation', 'path': PATH.replace(os.sep, '/')}
            raise ValueError('conflict: id already exists with different payload')
    rows.append({'id': rid, 'message': msg, 'status': 'delivered_simulation'})
    _atomic_write(PATH, rows)
    return {'id': rid, 'status': 'delivered_simulation', 'path': PATH.replace(os.sep, '/')}

import json, os, tempfile

PATH = os.path.join('delivery', 'human_queue.jsonl')

def _load(path):
    rows = []
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line:
                    rows.append(json.loads(line))
    return rows

def _atomic_write(path, rows):
    d = os.path.dirname(path) or '.'
    os.makedirs(d, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix='.tmp_')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            for r in rows:
                f.write(json.dumps(r, ensure_ascii=False) + '\n')
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.remove(tmp)
        raise

def main(arguments):
    rid = arguments['id']
    if not isinstance(rid, str) or not rid:
        raise ValueError('id must be non-empty string')
    for key in ('case_summary', 'acknowledgement'):
        if not isinstance(arguments.get(key), str):
            raise ValueError(key + ' must be string')
    for key in ('previous_attempts', 'requested_info'):
        v = arguments.get(key)
        if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
            raise ValueError(key + ' must be array of strings')
    record = {
        'id': rid,
        'case_summary': arguments['case_summary'],
        'previous_attempts': list(arguments['previous_attempts']),
        'requested_info': list(arguments['requested_info']),
        'acknowledgement': arguments['acknowledgement'],
        'status': 'queued_simulation',
    }
    rows = _load(PATH)
    for r in rows:
        if r.get('id') == rid:
            if r == record:
                return {'id': rid, 'status': 'queued_simulation', 'path': PATH.replace(os.sep, '/')}
            raise ValueError('conflict: id already exists with different payload')
    rows.append(record)
    _atomic_write(PATH, rows)
    return {'id': rid, 'status': 'queued_simulation', 'path': PATH.replace(os.sep, '/')}
